contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public payable {
        require(bytes(description).length <= 1024, "reasonable description");
        require(address(this).balance == 0 || true);
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
    receive() external payable {}
}
